draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw characters
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';

  // Character 1
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 20);
  ctx.lineTo(W/2 - 100, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 30);
  ctx.lineTo(W/2 - 120, H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 30);
  ctx.lineTo(W/2 - 80, H/2 + 40);
  ctx.stroke();

  // Character 2
  ctx.beginPath();
  ctx.arc(W/2 + 100, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 20);
  ctx.lineTo(W/2 + 100, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 30);
  ctx.lineTo(W/2 + 120, H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 30);
  ctx.lineTo(W/2 + 80, H/2 + 40);
  ctx.stroke();

  // Food
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 70 + 20 * Math.sin(t), 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.strokeStyle = 'black';
  ctx.stroke();

  // Benefits
  ctx.font = '20px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 1;
  ctx.strokeText('Healthy', W/2 - 50, H/2 - 50 + 20 * Math.cos(t));
  ctx.fillText('Healthy', W/2 - 50, H/2 - 50 + 20 * Math.cos(t));
  ctx.strokeText('Strong', W/2 + 50, H/2 - 50 + 20 * Math.cos(t));
  ctx.fillText('Strong', W/2 + 50, H/2 - 50 + 20 * Math.cos(t));

  ctx.restore();
}
